import { View, Text, TextInput, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [phone, setPhone] = useState("123");
  const invalid = phone.length !== 8;
  return (
    <View style={styles.screen}>
      <TextInput nativeID="phone" style={styles.input} placeholder="Утас (8 орон)" keyboardType="numeric"
        value={phone} onChangeText={setPhone} />
      {invalid && <Text nativeID="err" style={styles.errBase}>Утас 8 оронтой байх ёстой</Text>}
      {/* энд бичнэ үү: errBase-д улаан өнгө (color: "#dc2626") өг */}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 8, justifyContent: "center" },
  input: { borderWidth: 1, borderColor: "#cbd5e1", borderRadius: 10, padding: 14 },
  errBase: { fontSize: 13 },
});

registerRootComponent(App);

